package dashboard

import (
	"path/filepath"
	"sort"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/understand/graph"
)

// Layer is one card on the dashboard's overview view. Layers cluster files
// together by a deterministic rule (top-level directory + dominant file
// category) so a 16k-node graph collapses to ~5–30 cards humans can scan.
//
// The shape mirrors Understand-Anything's overview cards (title +
// description + file count + complexity badge + category color) without
// requiring semantic synthesis to populate. When the semantic stage
// eventually runs, layer descriptions and category assignments can be
// refined; this deterministic baseline holds the shape stable in the
// meantime.
type Layer struct {
	ID            string         `json:"id"`
	Title         string         `json:"title"`
	Path          string         `json:"path,omitempty"`
	Category      string         `json:"category"`
	Description   string         `json:"description"`
	FileCount     int            `json:"file_count"`
	SymbolCount   int            `json:"symbol_count,omitempty"`
	Complexity    string         `json:"complexity"`
	Languages     []string       `json:"languages,omitempty"`
	CheckpointHits int           `json:"checkpoint_hits,omitempty"`
	Hot           bool           `json:"hot,omitempty"`
	FileNodeIDs   []string       `json:"file_node_ids,omitempty"`
	Attrs         map[string]any `json:"attrs,omitempty"`
}

// LayerEdge is a count-weighted relation between layers. The weight is the
// number of file→file or file→checkpoint touchpoints between layer members,
// so a thicker edge means "these two layers move together more often".
type LayerEdge struct {
	From   string `json:"from"`
	To     string `json:"to"`
	Type   string `json:"type"`
	Weight int    `json:"weight"`
}

// LayerView is the JSON shape returned by /api/layers. Layers + the edges
// between them; the rest of the metadata sits on Layer.Attrs for forward
// compatibility.
type LayerView struct {
	Layers []Layer     `json:"layers"`
	Edges  []LayerEdge `json:"edges"`
}

// Category labels — match the Understand-Anything overview chips. Keep this
// list short and stable; rendering chooses a colour per category.
const (
	CategoryCode      = "CODE"
	CategoryConfig    = "CONFIG"
	CategoryDocs      = "DOCS"
	CategoryInfra     = "INFRA"
	CategoryData      = "DATA"
	CategoryTests     = "TESTS"
	CategoryDomain    = "DOMAIN"     // semantic-only; placeholder until synthesis runs
	CategoryKnowledge = "KNOWLEDGE"  // semantic-only
)

// computeLayers walks the fused graph and groups files into layers. Pure
// function — no I/O, no globals — so it's straightforward to unit-test
// against synthesized graphs.
func computeLayers(fused *graph.Slice) LayerView {
	if fused == nil {
		return LayerView{Layers: []Layer{}, Edges: []LayerEdge{}}
	}

	type bucket struct {
		layer Layer
		langs map[string]int
		files map[string]struct{}
	}
	buckets := map[string]*bucket{}
	fileToLayer := map[string]string{}

	for i := range fused.Nodes {
		n := &fused.Nodes[i]
		if n.Type != graph.NodeFile {
			continue
		}
		layerID, title, dir := layerIDForPath(n.Path)
		category := categorizeFile(n.Path, n.Language)
		b, ok := buckets[layerID]
		if !ok {
			b = &bucket{
				layer: Layer{
					ID:       layerID,
					Title:    title,
					Path:     dir,
					Category: category,
				},
				langs: map[string]int{},
				files: map[string]struct{}{},
			}
			buckets[layerID] = b
		}
		// First-file category wins for the layer; subsequent files refine
		// the category only when the bucket is empty.
		if b.layer.Category == "" {
			b.layer.Category = category
		}
		if n.Language != "" {
			b.langs[n.Language]++
		}
		b.layer.FileCount++
		b.layer.FileNodeIDs = append(b.layer.FileNodeIDs, n.ID)
		b.files[n.ID] = struct{}{}
		fileToLayer[n.ID] = layerID
	}

	// Symbol counts + checkpoint hits per layer.
	symCount := map[string]int{}
	cpHits := map[string]int{}
	containsByParent := map[string][]string{}
	touchedFile := map[string][]string{} // file -> cp ids

	for _, e := range fused.Edges {
		switch e.Type {
		case graph.EdgeContains:
			containsByParent[e.From] = append(containsByParent[e.From], e.To)
		case graph.EdgeTouchedIn:
			touchedFile[e.To] = append(touchedFile[e.To], e.From)
		}
	}
	for fileID := range fileToLayer {
		for _, child := range containsByParent[fileID] {
			// Only count nodes that look like symbols (id prefix sym:).
			if strings.HasPrefix(child, "sym:") {
				symCount[fileToLayer[fileID]]++
			}
		}
		cpHits[fileToLayer[fileID]] += len(touchedFile[fileID])
	}

	// Edges between layers — count of touched_in pairs that span layers.
	edgeWeights := map[string]map[string]int{}
	for _, e := range fused.Edges {
		if e.Type != graph.EdgeTouchedIn {
			continue
		}
		// "touched_in" goes cp -> file. Two files in the same checkpoint
		// implies a cross-layer link if their layers differ.
		// Group cp -> [files], then for each cp compute pairs.
	}
	// Build cp -> files map once.
	cpFiles := map[string][]string{}
	for _, e := range fused.Edges {
		if e.Type != graph.EdgeTouchedIn {
			continue
		}
		cpFiles[e.From] = append(cpFiles[e.From], e.To)
	}
	for _, files := range cpFiles {
		seenLayers := map[string]struct{}{}
		layerList := make([]string, 0, len(files))
		for _, f := range files {
			lid, ok := fileToLayer[f]
			if !ok {
				continue
			}
			if _, dup := seenLayers[lid]; dup {
				continue
			}
			seenLayers[lid] = struct{}{}
			layerList = append(layerList, lid)
		}
		sort.Strings(layerList)
		for i := 0; i < len(layerList); i++ {
			for j := i + 1; j < len(layerList); j++ {
				if edgeWeights[layerList[i]] == nil {
					edgeWeights[layerList[i]] = map[string]int{}
				}
				edgeWeights[layerList[i]][layerList[j]]++
			}
		}
	}

	// Materialize.
	view := LayerView{Layers: []Layer{}, Edges: []LayerEdge{}}
	for _, b := range buckets {
		layer := b.layer
		layer.SymbolCount = symCount[layer.ID]
		layer.CheckpointHits = cpHits[layer.ID]
		layer.Languages = sortedKeysByValueDesc(b.langs)
		layer.Description = describeLayer(layer)
		layer.Complexity = complexityFor(layer)
		layer.Hot = layer.CheckpointHits >= 25 || layer.FileCount >= 50
		view.Layers = append(view.Layers, layer)
	}
	sort.Slice(view.Layers, func(i, j int) bool {
		// Show heavier layers first by default, then alpha.
		if view.Layers[i].FileCount != view.Layers[j].FileCount {
			return view.Layers[i].FileCount > view.Layers[j].FileCount
		}
		return view.Layers[i].Title < view.Layers[j].Title
	})
	for from, peers := range edgeWeights {
		for to, w := range peers {
			view.Edges = append(view.Edges, LayerEdge{From: from, To: to, Type: "co_touched", Weight: w})
		}
	}
	sort.Slice(view.Edges, func(i, j int) bool {
		if view.Edges[i].Weight != view.Edges[j].Weight {
			return view.Edges[i].Weight > view.Edges[j].Weight
		}
		if view.Edges[i].From != view.Edges[j].From {
			return view.Edges[i].From < view.Edges[j].From
		}
		return view.Edges[i].To < view.Edges[j].To
	})
	return view
}

// layerIDForPath maps a repo-relative file path to a stable layer ID + a
// human-friendly title + the directory path. Files at the repo root get a
// dedicated "Project Root" layer; everything else is grouped by its
// top-level directory. Hidden (`.foo`) directories get their own layer.
func layerIDForPath(p string) (string, string, string) {
	p = filepath.ToSlash(p)
	if p == "" {
		return "layer:root", "Project Root", ""
	}
	idx := strings.IndexByte(p, '/')
	if idx < 0 {
		return "layer:root", "Project Root", ""
	}
	top := p[:idx]
	id := "layer:" + top
	title := humanizeDir(top)
	return id, title, top
}

// humanizeDir turns "cmd" → "Cmd", ".github" → ".github", "internal-api" →
// "Internal Api". Cheap heuristic; semantic synthesis can rewrite later.
func humanizeDir(d string) string {
	if d == "" {
		return "(root)"
	}
	if strings.HasPrefix(d, ".") {
		return d
	}
	parts := strings.FieldsFunc(d, func(r rune) bool { return r == '-' || r == '_' })
	for i, part := range parts {
		if part == "" {
			continue
		}
		parts[i] = strings.ToUpper(part[:1]) + part[1:]
	}
	return strings.Join(parts, " ")
}

// categorizeFile returns the chip category for a file's category color.
// Order matters — first match wins.
func categorizeFile(p, language string) string {
	lower := strings.ToLower(p)
	switch {
	case strings.Contains(lower, "/test") || strings.HasSuffix(lower, "_test.go") || strings.HasSuffix(lower, ".test.ts") || strings.HasSuffix(lower, "_test.py"):
		return CategoryTests
	case strings.HasPrefix(lower, ".github/") || strings.Contains(lower, "/terraform/") || strings.HasSuffix(lower, ".tf") || strings.Contains(lower, "/k8s/") || strings.Contains(lower, "/helm/"):
		return CategoryInfra
	case strings.HasSuffix(lower, ".md") || strings.HasSuffix(lower, ".rst") || strings.HasSuffix(lower, ".txt"):
		return CategoryDocs
	case strings.HasSuffix(lower, ".sql") || strings.HasSuffix(lower, ".csv") || strings.HasSuffix(lower, ".parquet") || strings.HasSuffix(lower, ".jsonl"):
		return CategoryData
	case strings.HasSuffix(lower, ".json") || strings.HasSuffix(lower, ".yaml") || strings.HasSuffix(lower, ".yml") || strings.HasSuffix(lower, ".toml") || strings.HasSuffix(lower, ".ini") || strings.HasSuffix(lower, ".env") || strings.Contains(filepath.Base(lower), "dockerfile"):
		return CategoryConfig
	}
	switch language {
	case "go", "python", "typescript", "javascript", "rust", "ruby", "java", "kotlin", "swift", "c", "cpp", "csharp":
		return CategoryCode
	case "markdown":
		return CategoryDocs
	case "json", "yaml", "toml":
		return CategoryConfig
	case "shell":
		return CategoryInfra
	}
	return CategoryCode
}

// describeLayer composes a deterministic 1-2 sentence description from
// counts + languages. When semantic synthesis is wired in this is replaced
// by the model-generated copy.
func describeLayer(l Layer) string {
	parts := []string{}
	if len(l.Languages) > 0 {
		langs := strings.Join(topN(l.Languages, 2), ", ")
		parts = append(parts, langs+" sources")
	}
	if l.SymbolCount > 0 {
		parts = append(parts, plural(l.SymbolCount, "symbol", "symbols"))
	}
	if l.CheckpointHits > 0 {
		parts = append(parts, plural(l.CheckpointHits, "checkpoint hit", "checkpoint hits"))
	}
	if len(parts) == 0 {
		return "Files grouped by directory."
	}
	desc := "Contains " + strings.Join(parts, ", ") + "."
	return desc
}

func plural(n int, one, many string) string {
	if n == 1 {
		return "1 " + one
	}
	return formatInt(n) + " " + many
}

func topN(in []string, n int) []string {
	if len(in) <= n {
		return in
	}
	return in[:n]
}

// complexityFor maps file count + language diversity to one of the three
// labels visible on Understand-Anything cards. Bands are deliberate and easy
// to override later; there's no science here, just a stable triage signal.
func complexityFor(l Layer) string {
	switch {
	case l.FileCount >= 50 || len(l.Languages) >= 4:
		return "complex"
	case l.FileCount >= 12 || len(l.Languages) >= 2:
		return "moderate"
	default:
		return "simple"
	}
}

func sortedKeysByValueDesc(m map[string]int) []string {
	type kv struct {
		k string
		v int
	}
	out := make([]kv, 0, len(m))
	for k, v := range m {
		out = append(out, kv{k: k, v: v})
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].v != out[j].v {
			return out[i].v > out[j].v
		}
		return out[i].k < out[j].k
	})
	res := make([]string, 0, len(out))
	for _, e := range out {
		res = append(res, e.k)
	}
	return res
}

func formatInt(n int) string {
	// avoids strconv import bloat in tests; this file is tiny.
	if n == 0 {
		return "0"
	}
	neg := false
	if n < 0 {
		neg = true
		n = -n
	}
	digits := ""
	for n > 0 {
		digits = string(rune('0'+n%10)) + digits
		n /= 10
	}
	if neg {
		return "-" + digits
	}
	return digits
}

