// handleLayers returns the deterministic layer overview that the dashboard's
// default "Overview" view renders as cards. Pure function over the fused
// graph; no provider call.
func (s *Server) handleLayers(w http.ResponseWriter, _ *http.Request) {
	fused, err := s.store.FusedGraph()
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	writeJSON(w, computeLayers(fused))
}

