/*
 * entire understand dashboard — dark theme.
 *
 * Layout:
 *   topbar          (view / mode / diff / chips / actions)
 *   searchbar       (full-width search with Fuzzy/Semantic toggle)
 *   main            (overview pill, cytoscape canvas, side panel)
 *   minimap         (bottom-right floating panel)
 *   zoom-controls   (bottom-left floating panel)
 *   timeline-bar    (footer, hidden until replay mode)
 */

:root {
  --bg: #0a0a0c;
  --bg-soft: #131319;
  --bg-card: #181821;
  --bg-card-hi: #20202b;
  --border: #2a2a36;
  --border-hi: #3a3a48;
  --fg: #e4e4ea;
  --fg-soft: #8b8b97;
  --fg-mute: #5f5f6c;
  --accent: #c9b97e;
  --accent-hi: #e8d49b;
  --pill: rgba(201,185,126,0.14);

  --layer-code: #b48feb;
  --layer-config: #6cb6ff;
  --layer-docs: #58c7ff;
  --layer-infra: #c69ef5;
  --layer-data: #65d39c;
  --layer-domain: #f0a878;
  --layer-knowledge: #d9b772;
  --layer-tests: #f08aa6;

  --complexity-simple: #4ea06d;
  --complexity-moderate: #c9b97e;
  --complexity-complex: #d97a7a;

  --shadow-card: 0 6px 18px rgba(0,0,0,0.55), 0 1px 3px rgba(0,0,0,0.6);
}

* { box-sizing: border-box; }
html, body { height: 100%; margin: 0; }
body {
  font: 13px/1.45 -apple-system, BlinkMacSystemFont, "Inter", "Segoe UI", sans-serif;
  background: var(--bg);
  color: var(--fg);
  display: grid;
  grid-template-rows: auto auto 1fr;
  min-height: 100vh;
  letter-spacing: 0.01em;
}

button { font: inherit; color: inherit; }
kbd {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 3px;
  padding: 1px 5px;
  font-family: ui-monospace, Menlo, monospace;
  font-size: 11px;
}

/* ────────────────────────────────────────────────────────── topbar */
.topbar {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 8px 16px;
  border-bottom: 1px solid var(--border);
  background: var(--bg);
  flex-wrap: wrap;
}
.brand { display: flex; align-items: center; gap: 8px; }
.brand h1 {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: -0.01em;
}
.brand .logo-dot {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--accent) 0%, var(--layer-code) 100%);
  box-shadow: 0 0 8px var(--accent);
}

.seg {
  display: inline-flex;
  align-items: center;
  background: var(--bg-soft);
  border: 1px solid var(--border);
  border-radius: 6px;
  overflow: hidden;
}
.seg button {
  border: 0;
  background: transparent;
  padding: 4px 10px;
  font-size: 11px;
  letter-spacing: 0.04em;
  color: var(--fg-soft);
  cursor: pointer;
  text-transform: capitalize;
}
.seg button.active {
  background: var(--bg-card);
  color: var(--fg);
}
.seg button:disabled {
  cursor: not-allowed;
  opacity: 0.4;
}

.chips {
  display: inline-flex;
  gap: 6px;
  flex-wrap: wrap;
  margin-left: 4px;
}
.chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 9px;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: var(--bg-soft);
  font-size: 10px;
  letter-spacing: 0.07em;
  font-weight: 600;
  color: var(--fg-soft);
  cursor: pointer;
  text-transform: uppercase;
}
.chip.on { color: var(--fg); background: var(--bg-card); border-color: var(--border-hi); }
.chip .swatch {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--fg-mute);
}
.chip[data-cat="CODE"] .swatch { background: var(--layer-code); }
.chip[data-cat="CONFIG"] .swatch { background: var(--layer-config); }
.chip[data-cat="DOCS"] .swatch { background: var(--layer-docs); }
.chip[data-cat="INFRA"] .swatch { background: var(--layer-infra); }
.chip[data-cat="DATA"] .swatch { background: var(--layer-data); }
.chip[data-cat="DOMAIN"] .swatch { background: var(--layer-domain); }
.chip[data-cat="KNOWLEDGE"] .swatch { background: var(--layer-knowledge); }
.chip[data-cat="TESTS"] .swatch { background: var(--layer-tests); }

.tally {
  font-size: 11px;
  color: var(--fg-soft);
  margin-left: auto;
}
.tally .dot {
  display: inline-block;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--accent);
  margin-right: 4px;
}

.topbar-actions { display: inline-flex; gap: 4px; }
.topbar-actions .ghost {
  background: transparent;
  border: 1px solid var(--border);
  color: var(--fg-soft);
  padding: 4px 9px;
  border-radius: 6px;
  font-size: 11px;
  cursor: pointer;
}
.topbar-actions .ghost:hover { color: var(--fg); border-color: var(--border-hi); }
.topbar-actions .ghost.circle {
  border-radius: 50%;
  width: 24px;
  height: 24px;
  padding: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

/* ────────────────────────────────────────────────────── searchbar */
.searchbar {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 16px;
  background: var(--bg);
  border-bottom: 1px solid var(--border);
}
.searchbar .search-icon { color: var(--fg-mute); margin-left: 4px; }
.searchbar input[type="search"] {
  flex: 1;
  padding: 6px 10px;
  background: var(--bg-soft);
  border: 1px solid var(--border);
  border-radius: 6px;
  color: var(--fg);
  font: inherit;
}
.searchbar input[type="search"]:focus { outline: none; border-color: var(--accent); }
.seg-search { flex: 0 0 auto; }

/* ────────────────────────────────────────────────────────── main */
main {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 360px;
  min-height: 0;
}
#cy {
  background: radial-gradient(circle at 50% 50%, rgba(255,255,255,0.02), transparent 60%), var(--bg);
  background-size: 100% 100%, auto;
  position: relative;
  overflow: hidden;
}
.overview-pill {
  position: absolute;
  top: 14px;
  left: 18px;
  padding: 4px 12px;
  border: 1px solid var(--border);
  background: var(--bg-soft);
  color: var(--fg);
  border-radius: 6px;
  font-size: 11px;
  letter-spacing: 0.08em;
  font-weight: 600;
  cursor: pointer;
  z-index: 50;
}

#status-banner {
  position: absolute;
  top: 60px;
  left: 50%;
  transform: translateX(-50%);
  background: rgba(56, 36, 18, 0.92);
  color: #f4d8a3;
  border: 1px solid rgba(244, 216, 163, 0.4);
  padding: 6px 14px;
  border-radius: 6px;
  font-size: 12px;
  z-index: 100;
  display: none;
}
#status-banner.visible { display: block; }

.press-help {
  position: absolute;
  top: 14px;
  right: 380px;
  font-size: 11px;
  color: var(--fg-mute);
}

/* ────────────────────────────────────────────────────────── side panel */
aside {
  border-left: 1px solid var(--border);
  background: var(--bg-soft);
  overflow-y: auto;
  display: flex;
  flex-direction: column;
}
.tabs {
  display: flex;
  border-bottom: 1px solid var(--border);
}
.tab {
  flex: 1;
  border: 0;
  padding: 10px 12px;
  background: transparent;
  color: var(--fg-mute);
  cursor: pointer;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.08em;
}
.tab.active {
  color: var(--fg);
  background: var(--bg);
  box-shadow: inset 0 -2px 0 var(--accent);
}
.tab-pane { display: none; padding: 16px; flex: 1 1 auto; }
.tab-pane.active { display: block; }

aside.empty .empty-msg { display: block; }
aside.empty .node-detail { display: none; }
aside:not(.empty) .empty-msg { display: none; }
aside:not(.empty) .node-detail { display: block; }

aside h2 {
  font-size: 18px;
  margin: 0 0 4px 0;
  letter-spacing: -0.01em;
}
aside h3 {
  font-size: 10px;
  letter-spacing: 0.1em;
  font-weight: 600;
  color: var(--fg-mute);
  margin: 16px 0 6px 0;
  text-transform: uppercase;
}
aside h3:first-child { margin-top: 0; }
aside .muted { color: var(--fg-soft); font-size: 12px; margin: 4px 0 16px 0; }
aside .meta-line { color: var(--fg-soft); font-size: 11px; margin-bottom: 8px; word-break: break-all; }
aside .badge-row { display: flex; gap: 4px; flex-wrap: wrap; margin-bottom: 12px; }
aside .badge {
  display: inline-block;
  padding: 2px 8px;
  border-radius: 999px;
  background: var(--pill);
  color: var(--accent-hi);
  font-size: 10px;
  letter-spacing: 0.06em;
  font-weight: 600;
  text-transform: uppercase;
}
aside .badge.complexity-simple { background: rgba(78, 160, 109, 0.15); color: var(--complexity-simple); }
aside .badge.complexity-moderate { background: rgba(201, 185, 126, 0.15); color: var(--complexity-moderate); }
aside .badge.complexity-complex { background: rgba(217, 122, 122, 0.15); color: var(--complexity-complex); }

aside button.primary {
  display: block;
  width: 100%;
  padding: 10px 14px;
  background: var(--bg-card);
  border: 1px solid var(--border-hi);
  color: var(--fg);
  border-radius: 6px;
  font: inherit;
  cursor: pointer;
  margin: 12px 0;
}
aside button.primary:hover { background: var(--bg-card-hi); }
aside button.back-btn {
  border: 0;
  background: transparent;
  color: var(--fg-soft);
  cursor: pointer;
  padding: 0;
  margin-bottom: 12px;
  font-size: 11px;
}
aside button.back-btn:hover { color: var(--fg); }

aside .conflict {
  background: rgba(217, 122, 122, 0.1);
  color: #e7a8a8;
  border: 1px solid rgba(217, 122, 122, 0.35);
  padding: 6px 10px;
  border-radius: 4px;
  font-size: 11px;
  margin-bottom: 12px;
}

aside ul, aside ol { list-style: none; padding: 0; margin: 0; }
aside ul li, aside ol li {
  padding: 6px 8px;
  border-radius: 4px;
  margin-bottom: 2px;
  font-size: 12px;
  cursor: pointer;
  display: flex;
  gap: 8px;
  align-items: flex-start;
}
aside ul li:hover, aside ol li:hover { background: var(--bg-card); }
aside ol.tour-steps { counter-reset: step; }
aside ol.tour-steps li {
  counter-increment: step;
  position: relative;
  padding-left: 32px;
}
aside ol.tour-steps li::before {
  content: counter(step) ".";
  position: absolute;
  left: 8px;
  color: var(--fg-mute);
  font-variant-numeric: tabular-nums;
}
aside ol.tour-steps li.active { background: var(--bg-card-hi); }

aside li .qualifier { color: var(--fg-mute); font-size: 10px; font-style: italic; display: block; }
aside li button.action {
  margin-left: auto;
  border: 1px solid var(--border);
  background: transparent;
  color: var(--fg-soft);
  border-radius: 4px;
  padding: 1px 8px;
  font-size: 10px;
  cursor: pointer;
}
aside li button.action:hover { color: var(--fg); border-color: var(--border-hi); }

aside section { margin-bottom: 8px; }

#layer-files li { font-family: ui-monospace, Menlo, monospace; font-size: 11px; }

/* ────────────────────────────────────────────────────────── minimap */
#minimap {
  position: absolute;
  right: 380px;
  bottom: 14px;
  width: 180px;
  height: 120px;
  background: rgba(10, 10, 12, 0.85);
  border: 1px solid var(--border);
  border-radius: 6px;
  overflow: hidden;
  z-index: 40;
}
#minimap-canvas { width: 100%; height: 100%; display: block; }
#minimap-viewport {
  position: absolute;
  border: 1.5px solid var(--accent);
  background: rgba(201, 185, 126, 0.08);
  pointer-events: none;
  border-radius: 2px;
}

/* ────────────────────────────────────────────────────────── zoom */
#zoom-controls {
  position: absolute;
  left: 14px;
  bottom: 14px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  z-index: 40;
}
#zoom-controls button {
  width: 28px;
  height: 28px;
  border: 1px solid var(--border);
  background: var(--bg-soft);
  color: var(--fg-soft);
  border-radius: 4px;
  cursor: pointer;
  font-size: 14px;
}
#zoom-controls button:hover { background: var(--bg-card); color: var(--fg); }

/* ────────────────────────────────────────────────────────── timeline */
footer {
  position: fixed;
  left: 0; right: 0; bottom: 0;
  background: var(--bg-soft);
  border-top: 1px solid var(--border);
  padding: 8px 16px;
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 12px;
  color: var(--fg-soft);
  z-index: 60;
}
footer.hidden { display: none; }
footer input[type="range"] { flex: 1; accent-color: var(--accent); }
footer .timeline-label { font-variant-numeric: tabular-nums; white-space: nowrap; }
footer .ghost {
  background: transparent;
  border: 1px solid var(--border);
  color: var(--fg-soft);
  padding: 3px 9px;
  border-radius: 4px;
  cursor: pointer;
  font-size: 11px;
}

// entire understand dashboard SPA — vanilla JS, no React, no transpiler.
//
// Bootstrap script tag injects the per-launch token into
// window.__entireUnderstandToken before this file loads. Every API call
// sends it as Authorization: Bearer; the token is never put in URLs.

(function () {
  "use strict";

  const TOKEN = window.__entireUnderstandToken;
  if (!TOKEN) {
    document.body.textContent = "missing bootstrap token; reload the page";
    return;
  }

  // ──────────────────────────────────────────────── api helpers
  function api(p) {
    return fetch(p, { headers: { Authorization: "Bearer " + TOKEN } }).then(function (r) {
      if (!r.ok) throw new Error(p + ": " + r.status);
      return r.json();
    });
  }

  // ──────────────────────────────────────────────── tiny DOM helpers
  function $(id) { return document.getElementById(id); }
  function el(tag, opts, kids) {
    const n = document.createElement(tag);
    if (opts) {
      if (opts.text != null) n.textContent = String(opts.text);
      if (opts.cls) n.className = opts.cls;
      if (opts.attrs) for (const k in opts.attrs) n.setAttribute(k, opts.attrs[k]);
      if (opts.click) n.addEventListener("click", opts.click);
    }
    if (kids) kids.forEach(function (k) { if (k) n.appendChild(k); });
    return n;
  }
  function clearChildren(node) { while (node.firstChild) node.removeChild(node.firstChild); }

  // ──────────────────────────────────────────────── banner
  function showBanner(msg) {
    const b = $("status-banner");
    b.textContent = msg;
    b.classList.add("visible");
  }
  function hideBanner() {
    const b = $("status-banner");
    b.classList.remove("visible");
    b.textContent = "";
  }

  // ──────────────────────────────────────────────── state
  let cy = null;
  let view = "overview";          // overview | learn | deep
  let manifest = null;
  let layerData = null;           // /api/layers
  let graphData = null;           // /api/graph
  let timeline = null;            // /api/timeline
  let activeCategoryFilter = null; // null = all
  const nodesByID = new Map();

  // ──────────────────────────────────────────────── chips
  // Categories are deterministic strings emitted by computeLayers in Go.
  // Each gets a cytoscape colour AND a chip with a coloured swatch.
  const CHIP_DEFS = [
    { cat: "CODE",      label: "code" },
    { cat: "CONFIG",    label: "config" },
    { cat: "DOCS",      label: "docs" },
    { cat: "INFRA",     label: "infra" },
    { cat: "DATA",      label: "data" },
    { cat: "TESTS",     label: "tests" },
    { cat: "DOMAIN",    label: "domain" },
    { cat: "KNOWLEDGE", label: "knowledge" },
  ];
  function renderChips(activeCats) {
    const root = $("chips");
    clearChildren(root);
    const present = new Set(activeCats);
    CHIP_DEFS.forEach(function (c) {
      if (!present.has(c.cat) && c.cat !== "DOMAIN" && c.cat !== "KNOWLEDGE") {
        return; // hide unused categories except the "future" semantic ones
      }
      const chip = el("button", {
        cls: "chip" + (activeCategoryFilter === c.cat ? " on" : ""),
        attrs: { "data-cat": c.cat, "type": "button" },
        click: function () {
          activeCategoryFilter = (activeCategoryFilter === c.cat) ? null : c.cat;
          renderChips(activeCats);
          applyFilters();
        },
      }, [
        el("span", { cls: "swatch" }),
        document.createTextNode(c.label),
      ]);
      if (!present.has(c.cat)) {
        chip.disabled = true;
        chip.title = "no layer in this category yet";
        chip.style.opacity = 0.35;
      }
      root.appendChild(chip);
    });
  }

  // ──────────────────────────────────────────────── tour
  function renderTour() {
    const summary = $("tour-summary");
    const stepsRoot = $("tour-steps");
    clearChildren(stepsRoot);

    const steps = buildTourSteps();
    summary.textContent = steps.length + " steps · Guided walkthrough of the codebase";

    steps.forEach(function (step, i) {
      const li = el("li", {
        click: function () { focusStep(step); $$("tour-steps", i); },
      });
      const title = el("div", { text: step.title });
      const meta = el("div", { cls: "qualifier", text: step.subtitle });
      li.appendChild(title);
      li.appendChild(meta);
      stepsRoot.appendChild(li);
    });
  }

  function $$(rootID, idx) {
    const root = $(rootID);
    if (!root) return;
    Array.prototype.forEach.call(root.children, function (li, i) {
      li.classList.toggle("active", i === idx);
    });
  }

  // buildTourSteps: deterministic ordering — overview, then top-N hottest
  // layers (by checkpoint hits), then the few non-hot but file-heavy layers.
  // Once semantic synthesis runs, this list gets richer titles + summaries.
  function buildTourSteps() {
    const steps = [{ id: null, title: "Project Overview", subtitle: "high-level layer map" }];
    if (!layerData) return steps;
    const sorted = layerData.layers.slice().sort(function (a, b) {
      const aHot = (a.checkpoint_hits || 0) + (a.file_count || 0) * 0.1;
      const bHot = (b.checkpoint_hits || 0) + (b.file_count || 0) * 0.1;
      return bHot - aHot;
    });
    sorted.slice(0, 14).forEach(function (l) {
      steps.push({
        id: l.id,
        title: l.title,
        subtitle: l.file_count + " files · " + l.complexity + (l.hot ? " · hot" : ""),
      });
    });
    return steps;
  }

  function focusStep(step) {
    if (!step.id) {
      cy.fit(undefined, 60);
      clearDetail();
      return;
    }
    const layer = (layerData.layers || []).find(function (l) { return l.id === step.id; });
    if (layer) selectLayer(layer);
    const ele = cy.getElementById(step.id);
    if (ele && !ele.empty()) {
      cy.animate({ center: { eles: ele }, zoom: Math.max(cy.zoom(), 0.75) }, { duration: 280 });
    }
  }

  // ──────────────────────────────────────────────── side panel
  function clearDetail() {
    $("detail").classList.add("empty");
    document.querySelectorAll("aside .tour-steps li.active").forEach(function (li) { li.classList.remove("active"); });
  }

  function selectLayer(layer) {
    const aside = $("detail");
    aside.classList.remove("empty");
    $("d-title").textContent = layer.title;
    $("d-meta").textContent = layer.path ? layer.path + "/" : "(repo root)";

    const badges = $("d-badges");
    clearChildren(badges);
    badges.appendChild(el("span", { text: layer.category, cls: "badge" }));
    if (layer.complexity) badges.appendChild(el("span", { text: layer.complexity, cls: "badge complexity-" + layer.complexity }));
    if (layer.hot) badges.appendChild(el("span", { text: "hot", cls: "badge complexity-complex" }));
    badges.appendChild(el("span", { text: layer.file_count + " files", cls: "badge" }));
    if (layer.symbol_count) badges.appendChild(el("span", { text: layer.symbol_count + " symbols", cls: "badge" }));

    $("d-conflict").hidden = true;

    const langs = $("d-langs");
    if (layer.languages && layer.languages.length) {
      $("d-langs-section").hidden = false;
      clearChildren(langs);
      layer.languages.slice(0, 6).forEach(function (l) {
        langs.appendChild(el("span", { text: l, cls: "badge" }));
      });
    } else {
      $("d-langs-section").hidden = true;
    }

    // Description
    const meta = $("d-meta");
    meta.textContent = (layer.path ? layer.path + "/ — " : "") + (layer.description || "");

    // Files list (FILES tab)
    const fl = $("layer-files");
    clearChildren(fl);
    (layer.file_node_ids || []).slice(0, 200).forEach(function (id) {
      const file = nodesByID.get(id);
      const path = file ? file.path : id;
      const li = el("li", {
        text: path,
        click: function () {
          // switch to "deep" view focused on this file
          switchView("deep");
          focusNode(id);
        },
      });
      fl.appendChild(li);
    });
    if ((layer.file_node_ids || []).length > 200) {
      fl.appendChild(el("li", { text: "…" + (layer.file_node_ids.length - 200) + " more", cls: "muted" }));
    }

    $("d-children-section").hidden = true;
    $("d-checkpoints-section").hidden = true;
    $("d-summary-section").hidden = true;
  }

  function selectNode(node) {
    const aside = $("detail");
    aside.classList.remove("empty");
    $("d-title").textContent = node.id;
    const meta = [];
    if (node.type) meta.push(node.type);
    if (node.symbol_kind) meta.push(node.symbol_kind);
    if (node.path) meta.push(node.path);
    if (node.language) meta.push(node.language);
    if (node.line_start) meta.push("L" + node.line_start + "-" + node.line_end);
    $("d-meta").textContent = meta.join(" · ");

    clearChildren($("d-badges"));
    $("d-conflict").hidden = true;
    $("d-langs-section").hidden = true;

    // Children (contains)
    const childList = $("d-children");
    clearChildren(childList);
    const children = childrenOf(node.id);
    if (children.length) {
      $("d-children-section").hidden = false;
      children.forEach(function (c) {
        const li = el("li", {
          text: c.label,
          click: function () { focusNode(c.id); },
        });
        childList.appendChild(li);
      });
    } else {
      $("d-children-section").hidden = true;
    }

    // Checkpoint trail
    const cps = checkpointsTouching(node.id);
    const cpList = $("d-checkpoints");
    clearChildren(cpList);
    if (cps.length) {
      $("d-checkpoints-section").hidden = false;
      cps.slice(0, 12).forEach(function (cp) {
        const li = el("li");
        const main = el("div");
        main.textContent = cp.id;
        li.appendChild(main);
        const q = el("div", { cls: "qualifier" });
        const parts = [];
        if (cp.created_at) parts.push(cp.created_at);
        if (cp.agent) parts.push(cp.agent);
        if (cp.scope === "file-owner") parts.push("(file-level inferred)");
        q.textContent = parts.join(" · ");
        li.appendChild(q);
        const btn = el("button", {
          text: "fetch detail",
          cls: "action",
          click: function (e) { e.stopPropagation(); loadCheckpointDetail(cp.id); },
        });
        li.appendChild(btn);
        cpList.appendChild(li);
      });
    } else {
      $("d-checkpoints-section").hidden = true;
    }

    $("d-summary-section").hidden = true;
  }

  function loadCheckpointDetail(cpID) {
    api("/api/checkpoint/" + encodeURIComponent(cpID))
      .then(function (cp) {
        $("d-summary-section").hidden = false;
        const root = $("d-summary");
        clearChildren(root);
        [
          ["checkpoint_id", cp.checkpoint_id],
          ["strategy", cp.strategy],
          ["branch", cp.branch],
          ["checkpoints_count", cp.checkpoints_count],
          ["session_count", cp.session_count],
        ].forEach(function (kv) {
          if (kv[1] == null || kv[1] === "" || kv[1] === 0) return;
          const li = el("li");
          li.appendChild(el("strong", { text: kv[0] + ": " }));
          li.appendChild(document.createTextNode(String(kv[1])));
          root.appendChild(li);
        });
        if (cp.files_touched && cp.files_touched.length) {
          const li = el("li");
          li.appendChild(el("strong", { text: "files (" + cp.files_touched.length + "):" }));
          const sub = el("ul");
          cp.files_touched.slice(0, 50).forEach(function (f) {
            const fli = el("li", {
              text: f,
              click: function () { switchView("deep"); focusNode("file:" + f); },
            });
            sub.appendChild(fli);
          });
          li.appendChild(sub);
          root.appendChild(li);
        }
      })
      .catch(function (err) { showBanner("checkpoint detail failed: " + err.message); });
  }

  // ──────────────────────────────────────────────── graph helpers
  function childrenOf(nodeID) {
    if (!cy) return [];
    const out = [];
    cy.edges('[type = "contains"][source = "' + cssEsc(nodeID) + '"]').forEach(function (e) {
      const tgt = cy.getElementById(e.data("target"));
      if (!tgt || tgt.empty()) return;
      const d = tgt.data();
      out.push({ id: d.id, label: d.name + (d.symbol_kind ? " · " + d.symbol_kind : "") });
    });
    return out;
  }

  function checkpointsTouching(nodeID) {
    if (!cy) return [];
    const seen = new Set();
    const out = [];
    cy.edges('[type = "touched_in"][target = "' + cssEsc(nodeID) + '"]').forEach(function (e) {
      const cp = cy.getElementById(e.data("source"));
      if (!cp || cp.empty()) return;
      const d = cp.data();
      if (seen.has(d.id)) return;
      seen.add(d.id);
      out.push({
        id: d.name,
        scope: e.data("scope") || "",
        created_at: (d.attrs && d.attrs.created_at) || "",
        agent: (d.attrs && d.attrs.agent) || "",
      });
    });
    out.sort(function (a, b) { return (b.created_at || "").localeCompare(a.created_at || ""); });
    return out;
  }

  function cssEsc(s) {
    return String(s).replace(/(["\\])/g, "\\$1");
  }

  // ──────────────────────────────────────────────── view switching
  function switchView(name) {
    if (view === name) return;
    view = name;
    document.querySelectorAll('.seg[data-seg="view"] button').forEach(function (b) {
      b.classList.toggle("active", b.dataset.view === name);
    });
    rerender();
  }

  function rerender() {
    if (!cy) return;
    cy.elements().remove();
    if (view === "overview" || view === "learn") {
      cy.add(buildLayerElements());
    } else {
      cy.add(buildDeepElements());
    }
    applyFilters();
    relayout();
  }

  // ──────────────────────────────────────────────── element builders
  function buildLayerElements() {
    if (!layerData) return [];
    const elements = [];
    layerData.layers.forEach(function (l) {
      elements.push({
        group: "nodes",
        data: {
          id: l.id,
          kind: "layer",
          title: l.title,
          path: l.path || "",
          category: l.category,
          complexity: l.complexity,
          file_count: l.file_count,
          symbol_count: l.symbol_count || 0,
          hot: l.hot || false,
          description: l.description || "",
          languages: l.languages || [],
          file_node_ids: l.file_node_ids || [],
          label: layerLabel(l),
        },
      });
    });
    layerData.edges.forEach(function (e, idx) {
      elements.push({
        group: "edges",
        data: {
          id: "le:" + idx,
          source: e.from,
          target: e.to,
          weight: e.weight,
          label: String(e.weight),
        },
      });
    });
    return elements;
  }

  function buildDeepElements() {
    if (!graphData) return [];
    const elements = [];
    graphData.nodes.forEach(function (n) {
      elements.push({
        group: "nodes",
        data: {
          id: n.id,
          kind: "raw",
          type: n.type,
          symbol_kind: n.symbol_kind,
          path: n.path,
          name: n.name,
          language: n.language,
          line_start: n.line_start,
          line_end: n.line_end,
          ghost: !!(n.attrs && n.attrs.removed),
          attrs: n.attrs || {},
          label: rawLabel(n),
        },
      });
    });
    graphData.edges.forEach(function (e) {
      elements.push({
        group: "edges",
        data: {
          id: e.id,
          source: e.from,
          target: e.to,
          type: e.type,
          scope: e.scope || "",
        },
      });
    });
    return elements;
  }

  function layerLabel(l) {
    return [
      l.category,
      l.complexity,
      "",
      l.title,
      "",
      l.description.length > 78 ? l.description.slice(0, 75) + "…" : l.description,
      "",
      l.file_count + " files",
    ].join("\n");
  }

  function rawLabel(n) {
    if (n.type === "checkpoint") return n.name.slice(0, 8);
    if (n.type === "session") return "sess";
    if (n.type === "package") return n.name;
    return n.name || n.id;
  }

  // ──────────────────────────────────────────────── filters
  function applyFilters() {
    if (!cy) return;
    cy.batch(function () {
      cy.nodes().forEach(function (n) {
        const cat = n.data("category");
        const visible = !activeCategoryFilter || (n.data("kind") === "layer" && cat === activeCategoryFilter) || n.data("kind") === "raw";
        n.style("display", visible ? "element" : "none");
      });
      cy.edges().forEach(function (e) {
        const src = cy.getElementById(e.data("source"));
        const tgt = cy.getElementById(e.data("target"));
        const visible = src && !src.empty() && tgt && !tgt.empty() &&
          src.style("display") !== "none" && tgt.style("display") !== "none";
        e.style("display", visible ? "element" : "none");
      });
    });
  }

  // ──────────────────────────────────────────────── layout
  function relayout() {
    if (!cy) return;
    const visibleCount = cy.nodes(":visible").length;
    let opts;
    if (view === "deep" && visibleCount > 1500) {
      opts = { name: "concentric", animate: false, fit: true };
    } else if (view === "deep" && visibleCount > 400) {
      opts = { name: "cose", animate: false, fit: true, nodeRepulsion: 4500, idealEdgeLength: 50 };
    } else if (view === "deep") {
      opts = { name: "dagre", rankDir: "TB", nodeSep: 30, rankSep: 60, animate: true, animationDuration: 350, fit: true };
    } else {
      opts = { name: "dagre", rankDir: "TB", nodeSep: 60, rankSep: 100, animate: true, animationDuration: 350, fit: true };
    }
    cy.layout(opts).run();
    if (cy && cy.center) setTimeout(updateMinimap, 400);
  }

  // ──────────────────────────────────────────────── minimap (hand-rolled)
  function updateMinimap() {
    if (!cy) return;
    const canvas = $("minimap-canvas");
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    const w = canvas.width = canvas.offsetWidth;
    const h = canvas.height = canvas.offsetHeight;
    ctx.clearRect(0, 0, w, h);

    const bb = cy.elements().boundingBox();
    if (!bb || !isFinite(bb.x1) || bb.w === 0 || bb.h === 0) return;
    const sx = w / bb.w, sy = h / bb.h;
    const scale = Math.min(sx, sy) * 0.9;
    const ox = (w - bb.w * scale) / 2;
    const oy = (h - bb.h * scale) / 2;

    cy.nodes(":visible").forEach(function (n) {
      const p = n.position();
      const sw = (n.width() || 8) * scale;
      const sh = (n.height() || 8) * scale;
      ctx.fillStyle = colorForNode(n) || "#888";
      ctx.fillRect(ox + (p.x - bb.x1) * scale - sw / 2, oy + (p.y - bb.y1) * scale - sh / 2, Math.max(sw, 2), Math.max(sh, 2));
    });

    // Viewport rectangle
    const ext = cy.extent();
    const vp = $("minimap-viewport");
    vp.style.left = (ox + (ext.x1 - bb.x1) * scale) + "px";
    vp.style.top = (oy + (ext.y1 - bb.y1) * scale) + "px";
    vp.style.width = ((ext.x2 - ext.x1) * scale) + "px";
    vp.style.height = ((ext.y2 - ext.y1) * scale) + "px";
  }

  function colorForNode(n) {
    if (n.data("kind") === "layer") return categoryColor(n.data("category"));
    const t = n.data("type");
    return ({
      file: "#6cb6ff",
      symbol: "#65d39c",
      directory: "#8b8b97",
      checkpoint: "#f0a878",
      session: "#b48feb",
      package: "#b48feb",
      repo: "#e4e4ea",
    })[t] || "#8b8b97";
  }
  function categoryColor(c) {
    return ({
      CODE: "#b48feb",
      CONFIG: "#6cb6ff",
      DOCS: "#58c7ff",
      INFRA: "#c69ef5",
      DATA: "#65d39c",
      DOMAIN: "#f0a878",
      KNOWLEDGE: "#d9b772",
      TESTS: "#f08aa6",
    })[c] || "#8b8b97";
  }

  // ──────────────────────────────────────────────── focus
  function focusNode(id) {
    if (!cy) return;
    const ele = cy.getElementById(id);
    if (!ele || ele.empty()) {
      showBanner("node " + id + " not in current view (try Deep Dive or clear filter)");
      return;
    }
    hideBanner();
    cy.elements().removeClass("highlight").removeClass("dim");
    ele.addClass("highlight");
    ele.neighborhood().addClass("highlight");
    cy.elements().difference(ele.neighborhood().union(ele)).addClass("dim");
    cy.animate({ center: { eles: ele }, zoom: Math.max(cy.zoom(), 0.9) }, { duration: 280 });
    if (ele.data("kind") === "layer") {
      const layer = layerData.layers.find(function (l) { return l.id === id; });
      if (layer) selectLayer(layer);
    } else {
      selectNode(ele.data());
    }
  }

  // ──────────────────────────────────────────────── search
  function wireSearch() {
    const input = $("search");
    let lastID = null;
    input.addEventListener("keydown", function (ev) {
      if (ev.key !== "Enter") return;
      const q = input.value.trim().toLowerCase();
      if (!q) return;
      // Search current view's elements first.
      let best = null;
      cy.nodes().forEach(function (n) {
        if (best) return;
        const haystack = [
          n.data("title"),
          n.data("name"),
          n.data("path"),
          n.data("description"),
          n.data("category"),
          n.id(),
        ].filter(Boolean).map(function (s) { return String(s).toLowerCase(); }).join(" ");
        if (haystack.includes(q) && n.id() !== lastID) best = n;
      });
      if (best) {
        lastID = best.id();
        focusNode(best.id());
      } else {
        showBanner("no match for: " + input.value);
      }
    });
  }

  // ──────────────────────────────────────────────── view buttons
  function wireSegments() {
    document.querySelectorAll('.seg[data-seg="view"] button').forEach(function (b) {
      b.addEventListener("click", function () {
        if (b.disabled) return;
        switchView(b.dataset.view);
      });
    });
  }

  function wireZoom() {
    $("zoom-in").addEventListener("click", function () { cy && cy.zoom(cy.zoom() * 1.25); updateMinimap(); });
    $("zoom-out").addEventListener("click", function () { cy && cy.zoom(cy.zoom() / 1.25); updateMinimap(); });
    $("zoom-fit").addEventListener("click", function () { cy && cy.fit(undefined, 40); updateMinimap(); });
    $("zoom-lock").addEventListener("click", function () {
      if (!cy) return;
      const u = cy.userPanningEnabled();
      cy.userPanningEnabled(!u);
      cy.userZoomingEnabled(!u);
      $("zoom-lock").textContent = u ? "🔓" : "🔒";
    });
    $("overview-pill").addEventListener("click", function () { switchView("overview"); });
    $("filter-btn").addEventListener("click", function () {
      activeCategoryFilter = null;
      renderChips(presentCategories());
      applyFilters();
    });
    $("export-btn").addEventListener("click", function () {
      if (!cy) return;
      const png = cy.png({ bg: "#0a0a0c", full: true });
      const a = document.createElement("a");
      a.href = png;
      a.download = "entire-understand.png";
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
    });
    $("path-btn").addEventListener("click", function () {
      showBanner("path selection coming once semantic synthesis is wired");
    });
    $("theme-btn").addEventListener("click", function () {
      showBanner("dark theme is the only theme in v1");
    });
    $("help-btn").addEventListener("click", function () {
      showBanner("Enter to search · click cards to drill in · ? for shortcuts (todo)");
    });

    // Tabs
    document.querySelectorAll(".tab").forEach(function (t) {
      t.addEventListener("click", function () {
        document.querySelectorAll(".tab").forEach(function (x) { x.classList.toggle("active", x === t); });
        document.querySelectorAll(".tab-pane").forEach(function (p) {
          p.classList.toggle("active", p.id === "tab-" + t.dataset.tab);
        });
      });
    });

    $("back-to-tour").addEventListener("click", clearDetail);
    $("start-tour-btn").addEventListener("click", function () {
      const steps = buildTourSteps();
      if (steps.length > 1) focusStep(steps[1]);
    });
  }

  function presentCategories() {
    const out = new Set();
    if (layerData) layerData.layers.forEach(function (l) { out.add(l.category); });
    return out;
  }

  // ──────────────────────────────────────────────── replay (deep view only)
  // Kept intentionally minimal in this revision; the layered overview view
  // doesn't show timeline events directly — user switches to Deep Dive for
  // that. Spec parity for replay v1 is text-CLI + Deep Dive UI.
  function wireReplay() { /* todo: integrate into deep view */ }

  // ──────────────────────────────────────────────── boot
  function boot() {
    Promise.all([
      api("/api/manifest"),
      api("/api/layers"),
      api("/api/graph"),
      api("/api/timeline"),
    ]).then(function (results) {
      manifest = results[0];
      layerData = results[1];
      graphData = results[2];
      timeline = results[3];

      const tally = $("tally");
      const layers = (layerData && layerData.layers) || [];
      tally.innerHTML = "";
      const ldot = el("span", { cls: "dot" });
      tally.appendChild(ldot);
      tally.appendChild(document.createTextNode(layers.length + " layers · "));
      const status = (manifest.semantic_status || "skipped").toLowerCase();
      tally.appendChild(document.createTextNode(status));
      if (manifest.checkpoint_head_changed) showBanner("cache may be stale — run `entire understand build`");

      // Indexes for quick lookups by raw graph node id.
      nodesByID.clear();
      (graphData.nodes || []).forEach(function (n) { nodesByID.set(n.id, n); });

      renderChips(presentCategories());
      renderTour();

      cy = cytoscape({
        container: $("cy"),
        elements: buildLayerElements(),
        wheelSensitivity: 0.2,
        minZoom: 0.05,
        maxZoom: 4,
        style: STYLE,
      });
      cy.on("tap", "node", function (ev) { focusNode(ev.target.id()); });
      cy.on("tap", function (ev) {
        if (ev.target === cy) {
          cy.elements().removeClass("highlight").removeClass("dim");
          clearDetail();
        }
      });
      cy.on("pan zoom", updateMinimap);

      relayout();
      wireSearch();
      wireSegments();
      wireZoom();
      wireReplay();

      const fragment = window.location.hash;
      if (fragment.indexOf("#area=") === 0) {
        const target = decodeURIComponent(fragment.slice("#area=".length));
        setTimeout(function () { switchView("deep"); focusNode(target); }, 600);
      }

      // Repo-name in the brand bar.
      $("repo-name").textContent = manifest.build_id ? "entire understand" : "entire understand";
    }).catch(function (err) {
      $("cy").textContent = "load failed: " + err.message;
    });
  }

  // ──────────────────────────────────────────────── style
  // Layer-card nodes are rendered as large rounded rectangles with a
  // category-colored left border (via cytoscape's pie-style decoration via
  // an extra side-coloured edge isn't trivial, so we use border-color +
  // background-color combinations). Multi-line label = title + description
  // + file count, packed via text-wrap.
  const STYLE = [
    {
      selector: "node",
      style: {
        "label": "data(label)",
        "color": "#e4e4ea",
        "text-valign": "center",
        "text-halign": "center",
        "text-wrap": "wrap",
        "text-max-width": 220,
        "font-size": 11,
        "font-family": "-apple-system, Segoe UI, sans-serif",
        "background-color": "#181821",
        "border-width": 1,
        "border-color": "#2a2a36",
      },
    },

    // Layer cards: large rounded rect, category-colored top border.
    {
      selector: 'node[kind = "layer"]',
      style: {
        "shape": "round-rectangle",
        "width": 240,
        "height": 130,
        "background-color": "#181821",
        "border-color": "#2a2a36",
        "border-width": 1,
        "padding": "10px",
        "text-valign": "center",
        "text-halign": "center",
        "text-wrap": "wrap",
        "text-max-width": 210,
        "font-size": 11,
        "font-weight": "normal",
        "color": "#e4e4ea",
      },
    },
    { selector: 'node[kind = "layer"][category = "CODE"]',      style: { "border-left-color": "#b48feb", "border-left-width": 4 } },
    { selector: 'node[kind = "layer"][category = "CONFIG"]',    style: { "border-left-color": "#6cb6ff", "border-left-width": 4 } },
    { selector: 'node[kind = "layer"][category = "DOCS"]',      style: { "border-left-color": "#58c7ff", "border-left-width": 4 } },
    { selector: 'node[kind = "layer"][category = "INFRA"]',     style: { "border-left-color": "#c69ef5", "border-left-width": 4 } },
    { selector: 'node[kind = "layer"][category = "DATA"]',      style: { "border-left-color": "#65d39c", "border-left-width": 4 } },
    { selector: 'node[kind = "layer"][category = "TESTS"]',     style: { "border-left-color": "#f08aa6", "border-left-width": 4 } },
    { selector: 'node[kind = "layer"][category = "DOMAIN"]',    style: { "border-left-color": "#f0a878", "border-left-width": 4 } },
    { selector: 'node[kind = "layer"][category = "KNOWLEDGE"]', style: { "border-left-color": "#d9b772", "border-left-width": 4 } },
    { selector: 'node[kind = "layer"][?hot]', style: { "border-color": "#d97a7a", "border-width": 1 } },

    // Raw-graph node colours (Deep Dive view).
    { selector: 'node[kind = "raw"][type = "repo"]',       style: { "background-color": "#e4e4ea", "shape": "ellipse", "width": 28, "height": 28 } },
    { selector: 'node[kind = "raw"][type = "directory"]',  style: { "background-color": "#8b8b97", "shape": "ellipse", "width": 14, "height": 14 } },
    { selector: 'node[kind = "raw"][type = "file"]',       style: { "background-color": "#6cb6ff", "shape": "ellipse", "width": 18, "height": 18 } },
    { selector: 'node[kind = "raw"][type = "symbol"]',     style: { "background-color": "#65d39c", "shape": "ellipse", "width": 12, "height": 12 } },
    { selector: 'node[kind = "raw"][type = "package"]',    style: { "background-color": "#b48feb", "shape": "diamond", "width": 14, "height": 14 } },
    { selector: 'node[kind = "raw"][type = "checkpoint"]', style: { "background-color": "#f0a878", "shape": "round-rectangle", "width": 14, "height": 12 } },
    { selector: 'node[kind = "raw"][type = "session"]',    style: { "background-color": "#b48feb", "shape": "round-rectangle", "width": 14, "height": 12 } },
    { selector: 'node[kind = "raw"][?ghost]',              style: { "background-color": "#d97a7a", "border-color": "#7f1d1d", "border-width": 2 } },

    // Edges
    {
      selector: "edge",
      style: {
        "width": 1,
        "line-color": "#3a3a48",
        "target-arrow-color": "#3a3a48",
        "target-arrow-shape": "triangle",
        "curve-style": "bezier",
        "label": "data(label)",
        "color": "#5f5f6c",
        "font-size": 9,
        "text-background-color": "#0a0a0c",
        "text-background-opacity": 1,
        "text-background-padding": 2,
      },
    },
    { selector: 'edge[type = "contains"]',    style: { "line-color": "#3a3a48", "target-arrow-color": "#3a3a48" } },
    { selector: 'edge[type = "imports"]',     style: { "line-color": "#6366f1", "target-arrow-color": "#6366f1", "line-style": "dashed" } },
    { selector: 'edge[type = "touched_in"]',  style: { "line-color": "#5a4a30", "target-arrow-color": "#5a4a30", "opacity": 0.45 } },
    { selector: 'edge[type = "belongs_to"]',  style: { "line-color": "#a855f7", "target-arrow-color": "#a855f7" } },

    { selector: ".highlight",                 style: { "border-width": 2, "border-color": "#c9b97e" } },
    { selector: "edge.highlight",             style: { "line-color": "#c9b97e", "target-arrow-color": "#c9b97e", "width": 2 } },
    { selector: ".dim",                       style: { "opacity": 0.18 } },
  ];

  boot();
})();

// entire understand dashboard SPA — vanilla JS, no React, no transpiler.
//
// Bootstrap script tag injects the per-launch token into
// window.__entireUnderstandToken before this file loads. Every API call
// sends it as Authorization: Bearer; the token is never put in URLs.

(function () {
  "use strict";

  const TOKEN = window.__entireUnderstandToken;
  if (!TOKEN) {
    document.body.textContent = "missing bootstrap token; reload the page";
    return;
  }

  // ──────────────────────────────────────────────── api helpers
  function api(p) {
    return fetch(p, { headers: { Authorization: "Bearer " + TOKEN } }).then(function (r) {
      if (!r.ok) throw new Error(p + ": " + r.status);
      return r.json();
    });
  }

  // ──────────────────────────────────────────────── tiny DOM helpers
  function $(id) { return document.getElementById(id); }
  function el(tag, opts, kids) {
    const n = document.createElement(tag);
    if (opts) {
      if (opts.text != null) n.textContent = String(opts.text);
      if (opts.cls) n.className = opts.cls;
      if (opts.attrs) for (const k in opts.attrs) n.setAttribute(k, opts.attrs[k]);
      if (opts.click) n.addEventListener("click", opts.click);
    }
    if (kids) kids.forEach(function (k) { if (k) n.appendChild(k); });
    return n;
  }
  function clearChildren(node) { while (node && node.firstChild) node.removeChild(node.firstChild); }

  // ──────────────────────────────────────────────── banner
  function showBanner(msg) {
    const b = $("status-banner");
    b.textContent = msg;
    b.classList.add("visible");
  }
  function hideBanner() {
    const b = $("status-banner");
    b.classList.remove("visible");
    b.textContent = "";
  }

  // ──────────────────────────────────────────────── state
  let cy = null;
  let view = "overview";          // overview | learn | deep
  let manifest = null;
  let layerData = null;           // /api/layers
  let graphData = null;           // /api/graph
  let timeline = null;            // /api/timeline (kept for future replay integration)
  let activeCategoryFilter = null;
  const nodesByID = new Map();

  // ──────────────────────────────────────────────── chip categories
  const CHIP_DEFS = [
    { cat: "CODE",      label: "code" },
    { cat: "CONFIG",    label: "config" },
    { cat: "DOCS",      label: "docs" },
    { cat: "INFRA",     label: "infra" },
    { cat: "DATA",      label: "data" },
    { cat: "TESTS",     label: "tests" },
    { cat: "DOMAIN",    label: "domain" },
    { cat: "KNOWLEDGE", label: "knowledge" },
  ];
  function renderChips(activeCats) {
    const root = $("chips");
    clearChildren(root);
    const present = new Set(activeCats);
    CHIP_DEFS.forEach(function (c) {
      if (!present.has(c.cat) && c.cat !== "DOMAIN" && c.cat !== "KNOWLEDGE") return;
      const chip = el("button", {
        cls: "chip" + (activeCategoryFilter === c.cat ? " on" : ""),
        attrs: { "data-cat": c.cat, "type": "button" },
        click: function () {
          activeCategoryFilter = (activeCategoryFilter === c.cat) ? null : c.cat;
          renderChips(activeCats);
          applyFilters();
        },
      }, [
        el("span", { cls: "swatch" }),
        document.createTextNode(c.label),
      ]);
      if (!present.has(c.cat)) {
        chip.disabled = true;
        chip.title = "no layer in this category yet";
        chip.style.opacity = 0.35;
      }
      root.appendChild(chip);
    });
  }

  // ──────────────────────────────────────────────── tour
  function renderTour() {
    const summary = $("tour-summary");
    const stepsRoot = $("tour-steps");
    clearChildren(stepsRoot);

    const steps = buildTourSteps();
    summary.textContent = steps.length + " steps · Guided walkthrough of the codebase";

    steps.forEach(function (step, i) {
      const li = el("li", {
        click: function () { focusStep(step); markActiveStep(i); },
      });
      li.appendChild(el("div", { text: step.title }));
      li.appendChild(el("div", { cls: "qualifier", text: step.subtitle }));
      stepsRoot.appendChild(li);
    });
  }

  function markActiveStep(idx) {
    const root = $("tour-steps");
    Array.prototype.forEach.call(root.children, function (li, i) {
      li.classList.toggle("active", i === idx);
    });
  }

  function buildTourSteps() {
    const steps = [{ id: null, title: "Project Overview", subtitle: "high-level layer map" }];
    if (!layerData) return steps;
    const sorted = layerData.layers.slice().sort(function (a, b) {
      const aHot = (a.checkpoint_hits || 0) + (a.file_count || 0) * 0.1;
      const bHot = (b.checkpoint_hits || 0) + (b.file_count || 0) * 0.1;
      return bHot - aHot;
    });
    sorted.slice(0, 14).forEach(function (l) {
      steps.push({
        id: l.id,
        title: l.title,
        subtitle: l.file_count + " files · " + l.complexity + (l.hot ? " · hot" : ""),
      });
    });
    return steps;
  }

  function focusStep(step) {
    if (!step.id) {
      cy.fit(undefined, 60);
      clearDetail();
      return;
    }
    const layer = (layerData.layers || []).find(function (l) { return l.id === step.id; });
    if (layer) selectLayer(layer);
    const ele = cy.getElementById(step.id);
    if (ele && !ele.empty()) {
      cy.animate({ center: { eles: ele }, zoom: Math.max(cy.zoom(), 0.75) }, { duration: 280 });
    }
  }

  // ──────────────────────────────────────────────── side panel
  function clearDetail() {
    $("detail").classList.add("empty");
    document.querySelectorAll("aside .tour-steps li.active").forEach(function (li) {
      li.classList.remove("active");
    });
  }

  function selectLayer(layer) {
    const aside = $("detail");
    aside.classList.remove("empty");
    $("d-title").textContent = layer.title;
    $("d-meta").textContent = (layer.path ? layer.path + "/ — " : "") + (layer.description || "");

    const badges = $("d-badges");
    clearChildren(badges);
    badges.appendChild(el("span", { text: layer.category, cls: "badge" }));
    if (layer.complexity) badges.appendChild(el("span", { text: layer.complexity, cls: "badge complexity-" + layer.complexity }));
    if (layer.hot) badges.appendChild(el("span", { text: "hot", cls: "badge complexity-complex" }));
    badges.appendChild(el("span", { text: layer.file_count + " files", cls: "badge" }));
    if (layer.symbol_count) badges.appendChild(el("span", { text: layer.symbol_count + " symbols", cls: "badge" }));

    $("d-conflict").hidden = true;

    const langs = $("d-langs");
    if (layer.languages && layer.languages.length) {
      $("d-langs-section").hidden = false;
      clearChildren(langs);
      layer.languages.slice(0, 6).forEach(function (l) {
        langs.appendChild(el("span", { text: l, cls: "badge" }));
      });
    } else {
      $("d-langs-section").hidden = true;
    }

    const fl = $("layer-files");
    clearChildren(fl);
    (layer.file_node_ids || []).slice(0, 200).forEach(function (id) {
      const file = nodesByID.get(id);
      const path = file ? file.path : id;
      fl.appendChild(el("li", {
        text: path,
        click: function () { switchView("deep"); focusNode(id); },
      }));
    });
    if ((layer.file_node_ids || []).length > 200) {
      fl.appendChild(el("li", { text: "…" + (layer.file_node_ids.length - 200) + " more", cls: "muted" }));
    }

    $("d-children-section").hidden = true;
    $("d-checkpoints-section").hidden = true;
    $("d-summary-section").hidden = true;
  }

  function selectNode(node) {
    const aside = $("detail");
    aside.classList.remove("empty");
    $("d-title").textContent = node.id;
    const meta = [];
    if (node.type) meta.push(node.type);
    if (node.symbol_kind) meta.push(node.symbol_kind);
    if (node.path) meta.push(node.path);
    if (node.language) meta.push(node.language);
    if (node.line_start) meta.push("L" + node.line_start + "-" + node.line_end);
    $("d-meta").textContent = meta.join(" · ");

    clearChildren($("d-badges"));
    $("d-conflict").hidden = true;
    $("d-langs-section").hidden = true;

    const childList = $("d-children");
    clearChildren(childList);
    const children = childrenOf(node.id);
    if (children.length) {
      $("d-children-section").hidden = false;
      children.forEach(function (c) {
        childList.appendChild(el("li", {
          text: c.label,
          click: function () { focusNode(c.id); },
        }));
      });
    } else {
      $("d-children-section").hidden = true;
    }

    const cps = checkpointsTouching(node.id);
    const cpList = $("d-checkpoints");
    clearChildren(cpList);
    if (cps.length) {
      $("d-checkpoints-section").hidden = false;
      cps.slice(0, 12).forEach(function (cp) {
        const li = el("li");
        li.appendChild(el("div", { text: cp.id }));
        const parts = [];
        if (cp.created_at) parts.push(cp.created_at);
        if (cp.agent) parts.push(cp.agent);
        if (cp.scope === "file-owner") parts.push("(file-level inferred)");
        li.appendChild(el("div", { cls: "qualifier", text: parts.join(" · ") }));
        li.appendChild(el("button", {
          text: "fetch detail",
          cls: "action",
          click: function (e) { e.stopPropagation(); loadCheckpointDetail(cp.id); },
        }));
        cpList.appendChild(li);
      });
    } else {
      $("d-checkpoints-section").hidden = true;
    }

    $("d-summary-section").hidden = true;
  }

  function loadCheckpointDetail(cpID) {
    api("/api/checkpoint/" + encodeURIComponent(cpID))
      .then(function (cp) {
        $("d-summary-section").hidden = false;
        const root = $("d-summary");
        clearChildren(root);
        [
          ["checkpoint_id", cp.checkpoint_id],
          ["strategy", cp.strategy],
          ["branch", cp.branch],
          ["checkpoints_count", cp.checkpoints_count],
          ["session_count", cp.session_count],
        ].forEach(function (kv) {
          if (kv[1] == null || kv[1] === "" || kv[1] === 0) return;
          const li = el("li");
          li.appendChild(el("strong", { text: kv[0] + ": " }));
          li.appendChild(document.createTextNode(String(kv[1])));
          root.appendChild(li);
        });
        if (cp.files_touched && cp.files_touched.length) {
          const li = el("li");
          li.appendChild(el("strong", { text: "files (" + cp.files_touched.length + "):" }));
          const sub = el("ul");
          cp.files_touched.slice(0, 50).forEach(function (f) {
            sub.appendChild(el("li", {
              text: f,
              click: function () { switchView("deep"); focusNode("file:" + f); },
            }));
          });
          li.appendChild(sub);
          root.appendChild(li);
        }
      })
      .catch(function (err) { showBanner("checkpoint detail failed: " + err.message); });
  }

  // ──────────────────────────────────────────────── graph helpers
  function childrenOf(nodeID) {
    if (!cy) return [];
    const out = [];
    cy.edges('[type = "contains"][source = "' + cssEsc(nodeID) + '"]').forEach(function (e) {
      const tgt = cy.getElementById(e.data("target"));
      if (!tgt || tgt.empty()) return;
      const d = tgt.data();
      out.push({ id: d.id, label: d.name + (d.symbol_kind ? " · " + d.symbol_kind : "") });
    });
    return out;
  }

  function checkpointsTouching(nodeID) {
    if (!cy) return [];
    const seen = new Set();
    const out = [];
    cy.edges('[type = "touched_in"][target = "' + cssEsc(nodeID) + '"]').forEach(function (e) {
      const cp = cy.getElementById(e.data("source"));
      if (!cp || cp.empty()) return;
      const d = cp.data();
      if (seen.has(d.id)) return;
      seen.add(d.id);
      out.push({
        id: d.name,
        scope: e.data("scope") || "",
        created_at: (d.attrs && d.attrs.created_at) || "",
        agent: (d.attrs && d.attrs.agent) || "",
      });
    });
    out.sort(function (a, b) { return (b.created_at || "").localeCompare(a.created_at || ""); });
    return out;
  }

  function cssEsc(s) {
    return String(s).replace(/(["\\])/g, "\\$1");
  }

  // ──────────────────────────────────────────────── view switching
  function switchView(name) {
    if (view === name) return;
    view = name;
    document.querySelectorAll('.seg[data-seg="view"] button').forEach(function (b) {
      b.classList.toggle("active", b.dataset.view === name);
    });
    rerender();
  }

  function rerender() {
    if (!cy) return;
    cy.elements().remove();
    if (view === "overview" || view === "learn") {
      cy.add(buildLayerElements());
    } else {
      cy.add(buildDeepElements());
    }
    applyFilters();
    relayout();
  }

  // ──────────────────────────────────────────────── element builders
  function buildLayerElements() {
    if (!layerData) return [];
    const elements = [];
    layerData.layers.forEach(function (l) {
      elements.push({
        group: "nodes",
        data: {
          id: l.id,
          kind: "layer",
          title: l.title,
          path: l.path || "",
          category: l.category,
          complexity: l.complexity,
          file_count: l.file_count,
          symbol_count: l.symbol_count || 0,
          hot: !!l.hot,
          description: l.description || "",
          languages: l.languages || [],
          file_node_ids: l.file_node_ids || [],
          label: layerLabel(l),
        },
      });
    });
    layerData.edges.forEach(function (e, idx) {
      elements.push({
        group: "edges",
        data: {
          id: "le:" + idx,
          source: e.from,
          target: e.to,
          weight: e.weight,
          label: String(e.weight),
        },
      });
    });
    return elements;
  }

  function buildDeepElements() {
    if (!graphData) return [];
    const elements = [];
    graphData.nodes.forEach(function (n) {
      elements.push({
        group: "nodes",
        data: {
          id: n.id,
          kind: "raw",
          type: n.type,
          symbol_kind: n.symbol_kind,
          path: n.path,
          name: n.name,
          language: n.language,
          line_start: n.line_start,
          line_end: n.line_end,
          ghost: !!(n.attrs && n.attrs.removed),
          attrs: n.attrs || {},
          label: rawLabel(n),
        },
      });
    });
    graphData.edges.forEach(function (e) {
      elements.push({
        group: "edges",
        data: {
          id: e.id,
          source: e.from,
          target: e.to,
          type: e.type,
          scope: e.scope || "",
        },
      });
    });
    return elements;
  }

  function layerLabel(l) {
    return [
      "LAYER · " + l.complexity,
      "",
      l.title,
      "",
      truncate(l.description || "", 78),
      "",
      l.file_count + " files",
    ].join("\n");
  }
  function truncate(s, n) { return s.length > n ? s.slice(0, n - 1) + "…" : s; }

  function rawLabel(n) {
    if (n.type === "checkpoint") return n.name.slice(0, 8);
    if (n.type === "session") return "sess";
    if (n.type === "package") return n.name;
    return n.name || n.id;
  }

  // ──────────────────────────────────────────────── filters
  function applyFilters() {
    if (!cy) return;
    cy.batch(function () {
      cy.nodes().forEach(function (n) {
        const cat = n.data("category");
        const visible = !activeCategoryFilter ||
          (n.data("kind") === "layer" && cat === activeCategoryFilter) ||
          n.data("kind") === "raw";
        n.style("display", visible ? "element" : "none");
      });
      cy.edges().forEach(function (e) {
        const src = cy.getElementById(e.data("source"));
        const tgt = cy.getElementById(e.data("target"));
        const visible = src && !src.empty() && tgt && !tgt.empty() &&
          src.style("display") !== "none" && tgt.style("display") !== "none";
        e.style("display", visible ? "element" : "none");
      });
    });
  }

  // ──────────────────────────────────────────────── layout
  function relayout() {
    if (!cy) return;
    const visibleCount = cy.nodes(":visible").length;
    let opts;
    if (view === "deep" && visibleCount > 1500) {
      opts = { name: "concentric", animate: false, fit: true };
    } else if (view === "deep" && visibleCount > 400) {
      opts = { name: "cose", animate: false, fit: true, nodeRepulsion: 4500, idealEdgeLength: 50 };
    } else if (view === "deep") {
      opts = { name: "dagre", rankDir: "TB", nodeSep: 30, rankSep: 60, animate: true, animationDuration: 350, fit: true };
    } else {
      opts = { name: "dagre", rankDir: "TB", nodeSep: 80, rankSep: 120, animate: true, animationDuration: 350, fit: true };
    }
    cy.layout(opts).run();
    setTimeout(updateMinimap, 400);
  }

  // ──────────────────────────────────────────────── minimap (hand-rolled)
  function updateMinimap() {
    if (!cy) return;
    const canvas = $("minimap-canvas");
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    const w = canvas.width = canvas.offsetWidth;
    const h = canvas.height = canvas.offsetHeight;
    ctx.clearRect(0, 0, w, h);

    const bb = cy.elements().boundingBox();
    if (!bb || !isFinite(bb.x1) || bb.w === 0 || bb.h === 0) return;
    const sx = w / bb.w, sy = h / bb.h;
    const scale = Math.min(sx, sy) * 0.9;
    const ox = (w - bb.w * scale) / 2;
    const oy = (h - bb.h * scale) / 2;

    cy.nodes(":visible").forEach(function (n) {
      const p = n.position();
      const sw = (n.width() || 8) * scale;
      const sh = (n.height() || 8) * scale;
      ctx.fillStyle = colorForNode(n) || "#888";
      ctx.fillRect(
        ox + (p.x - bb.x1) * scale - sw / 2,
        oy + (p.y - bb.y1) * scale - sh / 2,
        Math.max(sw, 2),
        Math.max(sh, 2)
      );
    });

    const ext = cy.extent();
    const vp = $("minimap-viewport");
    vp.style.left = (ox + (ext.x1 - bb.x1) * scale) + "px";
    vp.style.top = (oy + (ext.y1 - bb.y1) * scale) + "px";
    vp.style.width = ((ext.x2 - ext.x1) * scale) + "px";
    vp.style.height = ((ext.y2 - ext.y1) * scale) + "px";
  }

  function colorForNode(n) {
    if (n.data("kind") === "layer") return categoryColor(n.data("category"));
    const t = n.data("type");
    return ({
      file: "#6cb6ff",
      symbol: "#65d39c",
      directory: "#8b8b97",
      checkpoint: "#f0a878",
      session: "#b48feb",
      package: "#b48feb",
      repo: "#e4e4ea",
    })[t] || "#8b8b97";
  }
  function categoryColor(c) {
    return ({
      CODE: "#b48feb",
      CONFIG: "#6cb6ff",
      DOCS: "#58c7ff",
      INFRA: "#c69ef5",
      DATA: "#65d39c",
      DOMAIN: "#f0a878",
      KNOWLEDGE: "#d9b772",
      TESTS: "#f08aa6",
    })[c] || "#8b8b97";
  }

  // ──────────────────────────────────────────────── focus
  function focusNode(id) {
    if (!cy) return;
    const ele = cy.getElementById(id);
    if (!ele || ele.empty()) {
      showBanner("node " + id + " not in current view (try Deep Dive or clear filter)");
      return;
    }
    hideBanner();
    cy.elements().removeClass("highlight").removeClass("dim");
    ele.addClass("highlight");
    ele.neighborhood().addClass("highlight");
    cy.elements().difference(ele.neighborhood().union(ele)).addClass("dim");
    cy.animate({ center: { eles: ele }, zoom: Math.max(cy.zoom(), 0.9) }, { duration: 280 });
    if (ele.data("kind") === "layer") {
      const layer = layerData.layers.find(function (l) { return l.id === id; });
      if (layer) selectLayer(layer);
    } else {
      selectNode(ele.data());
    }
  }

  // ──────────────────────────────────────────────── search
  function wireSearch() {
    const input = $("search");
    let lastID = null;
    input.addEventListener("keydown", function (ev) {
      if (ev.key !== "Enter") return;
      const q = input.value.trim().toLowerCase();
      if (!q) return;
      let best = null;
      cy.nodes().forEach(function (n) {
        if (best) return;
        const haystack = [
          n.data("title"),
          n.data("name"),
          n.data("path"),
          n.data("description"),
          n.data("category"),
          n.id(),
        ].filter(Boolean).map(function (s) { return String(s).toLowerCase(); }).join(" ");
        if (haystack.includes(q) && n.id() !== lastID) best = n;
      });
      if (best) {
        lastID = best.id();
        focusNode(best.id());
      } else {
        showBanner("no match for: " + input.value);
      }
    });
  }

  // ──────────────────────────────────────────────── view buttons
  function wireSegments() {
    document.querySelectorAll('.seg[data-seg="view"] button').forEach(function (b) {
      b.addEventListener("click", function () {
        if (b.disabled) return;
        switchView(b.dataset.view);
      });
    });
  }

  function wireZoom() {
    $("zoom-in").addEventListener("click", function () { if (cy) { cy.zoom(cy.zoom() * 1.25); updateMinimap(); } });
    $("zoom-out").addEventListener("click", function () { if (cy) { cy.zoom(cy.zoom() / 1.25); updateMinimap(); } });
    $("zoom-fit").addEventListener("click", function () { if (cy) { cy.fit(undefined, 40); updateMinimap(); } });
    $("zoom-lock").addEventListener("click", function () {
      if (!cy) return;
      const u = cy.userPanningEnabled();
      cy.userPanningEnabled(!u);
      cy.userZoomingEnabled(!u);
      $("zoom-lock").textContent = u ? "🔓" : "🔒";
    });
    $("overview-pill").addEventListener("click", function () { switchView("overview"); });
    $("filter-btn").addEventListener("click", function () {
      activeCategoryFilter = null;
      renderChips(presentCategories());
      applyFilters();
    });
    $("export-btn").addEventListener("click", function () {
      if (!cy) return;
      const png = cy.png({ bg: "#0a0a0c", full: true });
      const a = document.createElement("a");
      a.href = png;
      a.download = "entire-understand.png";
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
    });
    $("path-btn").addEventListener("click", function () {
      showBanner("path selection arrives once semantic synthesis is wired");
    });
    $("theme-btn").addEventListener("click", function () {
      showBanner("dark theme is the only theme in v1");
    });
    $("help-btn").addEventListener("click", function () {
      showBanner("Enter to search · click cards to drill in · keyboard help is todo");
    });

    document.querySelectorAll(".tab").forEach(function (t) {
      t.addEventListener("click", function () {
        document.querySelectorAll(".tab").forEach(function (x) { x.classList.toggle("active", x === t); });
        document.querySelectorAll(".tab-pane").forEach(function (p) {
          p.classList.toggle("active", p.id === "tab-" + t.dataset.tab);
        });
      });
    });

    $("back-to-tour").addEventListener("click", clearDetail);
    $("start-tour-btn").addEventListener("click", function () {
      const steps = buildTourSteps();
      if (steps.length > 1) focusStep(steps[1]);
    });
  }

  function presentCategories() {
    const out = new Set();
    if (layerData) layerData.layers.forEach(function (l) { out.add(l.category); });
    return out;
  }

  // ──────────────────────────────────────────────── boot
  function boot() {
    Promise.all([
      api("/api/manifest"),
      api("/api/layers"),
      api("/api/graph"),
      api("/api/timeline"),
    ]).then(function (results) {
      manifest = results[0];
      layerData = results[1];
      graphData = results[2];
      timeline = results[3]; void timeline;

      const tally = $("tally");
      clearChildren(tally);
      const layers = (layerData && layerData.layers) || [];
      tally.appendChild(el("span", { cls: "dot" }));
      tally.appendChild(document.createTextNode(layers.length + " layers · "));
      const status = (manifest.semantic_status || "skipped").toLowerCase();
      tally.appendChild(document.createTextNode(status));
      if (manifest.checkpoint_head_changed) {
        showBanner("cache may be stale — run `entire understand build`");
      }

      nodesByID.clear();
      (graphData.nodes || []).forEach(function (n) { nodesByID.set(n.id, n); });

      renderChips(presentCategories());
      renderTour();

      cy = cytoscape({
        container: $("cy"),
        elements: buildLayerElements(),
        wheelSensitivity: 0.2,
        minZoom: 0.05,
        maxZoom: 4,
        style: STYLE,
      });
      cy.on("tap", "node", function (ev) { focusNode(ev.target.id()); });
      cy.on("tap", function (ev) {
        if (ev.target === cy) {
          cy.elements().removeClass("highlight").removeClass("dim");
          clearDetail();
        }
      });
      cy.on("pan zoom", updateMinimap);

      relayout();
      wireSearch();
      wireSegments();
      wireZoom();

      const fragment = window.location.hash;
      if (fragment.indexOf("#area=") === 0) {
        const target = decodeURIComponent(fragment.slice("#area=".length));
        setTimeout(function () { switchView("deep"); focusNode(target); }, 600);
      }
    }).catch(function (err) {
      $("cy").textContent = "load failed: " + err.message;
    });
  }

  // ──────────────────────────────────────────────── style
  const STYLE = [
    {
      selector: "node",
      style: {
        "label": "data(label)",
        "color": "#e4e4ea",
        "text-valign": "center",
        "text-halign": "center",
        "text-wrap": "wrap",
        "text-max-width": 220,
        "font-size": 11,
        "font-family": "-apple-system, Segoe UI, sans-serif",
        "background-color": "#181821",
        "border-width": 1,
        "border-color": "#2a2a36",
      },
    },
    {
      selector: 'node[kind = "layer"]',
      style: {
        "shape": "round-rectangle",
        "width": 240,
        "height": 130,
        "background-color": "#181821",
        "border-color": "#2a2a36",
        "border-width": 1,
        "padding": "10px",
        "text-valign": "center",
        "text-halign": "center",
        "text-wrap": "wrap",
        "text-max-width": 210,
        "font-size": 11,
        "color": "#e4e4ea",
      },
    },
    { selector: 'node[kind = "layer"][?hot]', style: { "border-color": "#d97a7a", "border-width": 1 } },

    { selector: 'node[kind = "raw"][type = "repo"]',       style: { "background-color": "#e4e4ea", "shape": "ellipse", "width": 28, "height": 28 } },
    { selector: 'node[kind = "raw"][type = "directory"]',  style: { "background-color": "#8b8b97", "shape": "ellipse", "width": 14, "height": 14 } },
    { selector: 'node[kind = "raw"][type = "file"]',       style: { "background-color": "#6cb6ff", "shape": "ellipse", "width": 18, "height": 18 } },
    { selector: 'node[kind = "raw"][type = "symbol"]',     style: { "background-color": "#65d39c", "shape": "ellipse", "width": 12, "height": 12 } },
    { selector: 'node[kind = "raw"][type = "package"]',    style: { "background-color": "#b48feb", "shape": "diamond", "width": 14, "height": 14 } },
    { selector: 'node[kind = "raw"][type = "checkpoint"]', style: { "background-color": "#f0a878", "shape": "round-rectangle", "width": 14, "height": 12 } },
    { selector: 'node[kind = "raw"][type = "session"]',    style: { "background-color": "#b48feb", "shape": "round-rectangle", "width": 14, "height": 12 } },
    { selector: 'node[kind = "raw"][?ghost]',              style: { "background-color": "#d97a7a", "border-color": "#7f1d1d", "border-width": 2 } },

    {
      selector: "edge",
      style: {
        "width": 1,
        "line-color": "#3a3a48",
        "target-arrow-color": "#3a3a48",
        "target-arrow-shape": "triangle",
        "curve-style": "bezier",
        "label": "data(label)",
        "color": "#5f5f6c",
        "font-size": 9,
        "text-background-color": "#0a0a0c",
        "text-background-opacity": 1,
        "text-background-padding": 2,
      },
    },
    { selector: 'edge[type = "contains"]',    style: { "line-color": "#3a3a48", "target-arrow-color": "#3a3a48" } },
    { selector: 'edge[type = "imports"]',     style: { "line-color": "#6366f1", "target-arrow-color": "#6366f1", "line-style": "dashed" } },
    { selector: 'edge[type = "touched_in"]',  style: { "line-color": "#5a4a30", "target-arrow-color": "#5a4a30", "opacity": 0.45 } },
    { selector: 'edge[type = "belongs_to"]',  style: { "line-color": "#a855f7", "target-arrow-color": "#a855f7" } },

    { selector: ".highlight",                 style: { "border-width": 2, "border-color": "#c9b97e" } },
    { selector: "edge.highlight",             style: { "line-color": "#c9b97e", "target-arrow-color": "#c9b97e", "width": 2 } },
    { selector: ".dim",                       style: { "opacity": 0.18 } },
  ];

  boot();
})();

package dashboard

