func TestComputeLayers_GroupsByTopLevelDir(t *testing.T) {
	t.Parallel()

	fused := &graph.Slice{
		Nodes: []graph.Node{
			{ID: "file:cmd/main.go", Type: graph.NodeFile, Name: "main.go", Path: "cmd/main.go", Language: "go"},
			{ID: "file:cmd/util.go", Type: graph.NodeFile, Name: "util.go", Path: "cmd/util.go", Language: "go"},
			{ID: "file:docs/readme.md", Type: graph.NodeFile, Name: "readme.md", Path: "docs/readme.md", Language: "markdown"},
			{ID: "file:.github/workflows/ci.yaml", Type: graph.NodeFile, Name: "ci.yaml", Path: ".github/workflows/ci.yaml", Language: "yaml"},
			{ID: "file:README.md", Type: graph.NodeFile, Name: "README.md", Path: "README.md", Language: "markdown"},
		},
	}

	view := computeLayers(fused)

	got := map[string]Layer{}
	for _, l := range view.Layers {
		got[l.ID] = l
	}

	if _, ok := got["layer:cmd"]; !ok {
		t.Errorf("expected layer:cmd; got=%+v", layerIDs(view.Layers))
	}
	if _, ok := got["layer:docs"]; !ok {
		t.Errorf("expected layer:docs")
	}
	if _, ok := got["layer:.github"]; !ok {
		t.Errorf("expected layer:.github")
	}
	if _, ok := got["layer:root"]; !ok {
		t.Errorf("expected root layer for README.md")
	}

	cmd := got["layer:cmd"]
	if cmd.FileCount != 2 {
		t.Errorf("layer:cmd FileCount=%d; want 2", cmd.FileCount)
	}
	if cmd.Category != CategoryCode {
		t.Errorf("layer:cmd Category=%q; want CODE", cmd.Category)
	}
	if cmd.Complexity != "simple" {
		t.Errorf("layer:cmd Complexity=%q; want simple (2 files)", cmd.Complexity)
	}

	docs := got["layer:docs"]
	if docs.Category != CategoryDocs {
		t.Errorf("layer:docs Category=%q; want DOCS", docs.Category)
	}

	infra := got["layer:.github"]
	if infra.Category != CategoryInfra {
		t.Errorf("layer:.github Category=%q; want INFRA", infra.Category)
	}
}

func TestComputeLayers_ComplexityBands(t *testing.T) {
	t.Parallel()

	mkFiles := func(prefix string, n int, lang string) []graph.Node {
		out := make([]graph.Node, 0, n)
		for i := 0; i < n; i++ {
			path := prefix + "/file" + intToStr(i) + ".go"
			out = append(out, graph.Node{
				ID:       "file:" + path,
				Type:     graph.NodeFile,
				Name:     "file" + intToStr(i) + ".go",
				Path:     path,
				Language: lang,
			})
		}
		return out
	}

	cases := []struct {
		dir    string
		count  int
		lang   string
		want   string
	}{
		{"small", 5, "go", "simple"},
		{"mid", 20, "go", "moderate"},
		{"big", 80, "go", "complex"},
	}
	for _, c := range cases {
		fused := &graph.Slice{Nodes: mkFiles(c.dir, c.count, c.lang)}
		view := computeLayers(fused)
		if len(view.Layers) != 1 {
			t.Fatalf("%s: expected 1 layer; got %d", c.dir, len(view.Layers))
		}
		if got := view.Layers[0].Complexity; got != c.want {
			t.Errorf("%s (%d files): complexity=%q; want %q", c.dir, c.count, got, c.want)
		}
	}
}

func TestComputeLayers_CrossLayerEdgesFromSharedCheckpoints(t *testing.T) {
	t.Parallel()

	fused := &graph.Slice{
		Nodes: []graph.Node{
			{ID: "file:cmd/main.go", Type: graph.NodeFile, Path: "cmd/main.go", Language: "go"},
			{ID: "file:lib/util.go", Type: graph.NodeFile, Path: "lib/util.go", Language: "go"},
			{ID: "cp:abc", Type: graph.NodeCheckpoint, Name: "abc"},
		},
		Edges: []graph.Edge{
			{From: "cp:abc", To: "file:cmd/main.go", Type: graph.EdgeTouchedIn},
			{From: "cp:abc", To: "file:lib/util.go", Type: graph.EdgeTouchedIn},
		},
	}

	view := computeLayers(fused)
	if len(view.Edges) != 1 {
		t.Fatalf("edges=%d; want 1 cross-layer edge", len(view.Edges))
	}
	e := view.Edges[0]
	if !((e.From == "layer:cmd" && e.To == "layer:lib") || (e.From == "layer:lib" && e.To == "layer:cmd")) {
		t.Errorf("edge endpoints unexpected: %+v", e)
	}
	if e.Weight != 1 {
		t.Errorf("edge.Weight=%d; want 1", e.Weight)
	}
}

func TestServer_LayersEndpoint(t *testing.T) {
	t.Parallel()
	srv, h := newHandler(t) // makeStore seeds 1 file (main.go) at root + 1 cp.
	rec := httptest.NewRecorder()
	req := httptest.NewRequestWithContext(t.Context(), http.MethodGet, "/api/layers", http.NoBody)
	req.Header.Set("Authorization", "Bearer "+srv.Token())
	h.ServeHTTP(rec, req)
	if rec.Code != http.StatusOK {
		t.Fatalf("status=%d; want 200", rec.Code)
	}

	body, err := io.ReadAll(rec.Body)
	if err != nil {
		t.Fatalf("read body: %v", err)
	}
	var got LayerView
	if err := json.Unmarshal(body, &got); err != nil {
